text:
{
  "questions": [
    {
      "n": 1,
      "start": "Wie wird die Arbeitsbelastung heute",
      "end": "von Schulleiterinnen und Schulleitern eingeschätzt"
    },
    {
      "n": 2,
      "start": "Wie sieht die heutige Ausgestaltung",
      "end": "der SL-Pensen aus?"
    },
    {
      "n": 3,
      "start": "Welche Massnahmen bzw. welche Mehrpensen",
      "end": "würden die Arbeitsbelastung der SL massgeblich verringern"
    },
    {
      "n": 4,
      "start": "Gibt es bereits Projekte/Lösungsansätze,",
      "end": "welche konkret auf die Erleichterung der Arbeitsbelastung hinzielen?"
    },
    {
      "n": 5,
      "start": "Könnte die Schaffung eines Sekretariats",
      "end": "eine mögliche Lösung zur Arbeitslastsenkung in Bezug auf administrativen Aufwand sein?"
    },
    {
      "n": 6,
      "start": "Welche anderen Lösungsansätze werden",
      "end": "in der Bildungsdirektion besprochen?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Die Arbeitsbelastung ist insgesamt als",
      "end": "eher hoch bis sehr hoch einzuschätzen."
    },
    {
      "n": 2,
      "start": "Aufgrund der Grösse der städtischen Schulbetriebseinheiten",
      "end": "werden viele Primarschuleinheiten mit Co-Leitungen geführt."
    },
    {
      "n": 3,
      "start": "Die Reduktion von administrativen Arbeiten würde für die Schulleitungen",
      "end": "zu einer Entlastung führen."
    },
    {
      "n": 4,
      "start": "Die Volksschule Stadt Luzern hat im Frühling 2023 das Führungs- und Organisationsentwicklungsprojekt",
      "end": "«Move2Lead» initiiert."
    },
    {
      "n": 5,
      "start": "Ja. Die Schaffung bzw. der Ausbau der dezentralen Sekretariate in den Schulbetriebseinheiten",
      "end": "könnte eine mögliche Lösung für die administrative Entlastung sein."
    },
    {
      "n": 6,
      "start": "Es wurden bisher neben den Lösungsansätzen gemäss den Ausführungen in der Antwort auf Frage 4",
      "end": "noch keine weiteren Ansätze besprochen."
    }
  ],
  "submitter": "Silvana E. S. Leasi und Diel Tatjana Schmid Meyer",
  "co_signatories": ["Mitte-Fraktion"],
  "recommendation": "none",
  "reasoning": null
}
